export function parseDuration(text: string): number {
  const multipliers: Record<string, number> = { h: 3600000, m: 60000, s: 1000, ms: 1 };
  // unit order index: h=0, m=1, s=2, ms=3
  const unitOrder: Record<string, number> = { h: 0, m: 1, s: 2, ms: 3 };

  const s = text.trim();
  if (!s) throw new RangeError('Invalid duration');

  let pos = 0;
  let total = 0;
  let lastOrder = -1;
  let count = 0;

  while (pos < s.length) {
    // skip inter-component spaces
    while (pos < s.length && s[pos] === ' ') pos++;
    if (pos >= s.length) break;

    // parse digits
    const start = pos;
    while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
    if (pos === start) throw new RangeError('Invalid duration');
    const numStr = s.slice(start, pos);

    // parse unit (ms before s to avoid partial match)
    let unit: string;
    if (s.startsWith('ms', pos)) { unit = 'ms'; pos += 2; }
    else if (s[pos] === 'h') { unit = 'h'; pos += 1; }
    else if (s[pos] === 'm') { unit = 'm'; pos += 1; }
    else if (s[pos] === 's') { unit = 's'; pos += 1; }
    else throw new RangeError('Invalid duration');

    // strictly descending order
    const order = unitOrder[unit];
    if (order <= lastOrder) throw new RangeError('Invalid duration');
    lastOrder = order;

    const val = Number(numStr);
    if (!Number.isSafeInteger(val)) throw new RangeError('Invalid duration');

    const contribution = val * multipliers[unit];
    if (contribution > Number.MAX_SAFE_INTEGER) throw new RangeError('Invalid duration');

    total += contribution;
    if (!Number.isSafeInteger(total)) throw new RangeError('Invalid duration');

    count++;
  }

  if (count === 0) throw new RangeError('Invalid duration');
  return total;
}

const UNITS = ['h', 'm', 's', 'ms'] as const;
type Unit = (typeof UNITS)[number];
const MS: Record<Unit, number> = { h: 3600000, m: 60000, s: 1000, ms: 1 };
const COMPONENT_RE = /^(\d+)(h|ms|m|s)/;
const MAX = Number.MAX_SAFE_INTEGER;

export function parseDuration(text: string): number {
  let pos = /^\s*/.exec(text)![0].length;
  let lastUnitIndex = -1;
  let total = 0;
  let parsed = false;

  while (pos < text.length) {
    const match = COMPONENT_RE.exec(text.slice(pos));
    if (!match) throw new RangeError('Invalid duration');

    const value = Number(match[1]);
    if (value > MAX) throw new RangeError('Invalid duration');

    const unit = match[2] as Unit;
    const unitIndex = UNITS.indexOf(unit);
    if (unitIndex <= lastUnitIndex) throw new RangeError('Invalid duration');
    lastUnitIndex = unitIndex;

    const contribution = value * MS[unit];
    if (contribution > MAX) throw new RangeError('Invalid duration');
    total += contribution;
    if (total > MAX) throw new RangeError('Invalid duration');

    pos += match[0].length;
    parsed = true;
    pos += /^\s*/.exec(text.slice(pos))![0].length;
  }

  if (!parsed) throw new RangeError('Invalid duration');
  return total;
}

export function parseDuration(text: string): number {
  const trimmed = text.trim();
  if (!trimmed) throw new RangeError('Invalid duration');

  // Validate: one or more components (digits + unit), separated by optional whitespace.
  // ms must precede m in the alternation so "ms" is tried first.
  if (!/^\d+(?:h|ms|m|s)(?:\s*\d+(?:h|ms|m|s))*$/.test(trimmed)) {
    throw new RangeError('Invalid duration');
  }

  const unitOrder = ['h', 'm', 's', 'ms'];
  const unitMultipliers: Record<string, number> = {
    h: 3_600_000,
    m:    60_000,
    s:     1_000,
    ms:        1,
  };

  const tokenRegex = /(\d+)(h|ms|m|s)/g;
  let total = 0;
  let lastUnitIndex = -1;
  let match: RegExpExecArray | null;

  while ((match = tokenRegex.exec(trimmed)) !== null) {
    const unit = match[2];
    const unitIndex = unitOrder.indexOf(unit);

    // Units must appear in strictly descending order (no repeats, no going back).
    if (unitIndex <= lastUnitIndex) throw new RangeError('Invalid duration');
    lastUnitIndex = unitIndex;

    const value = Number(match[1]);
    if (!Number.isSafeInteger(value)) throw new RangeError('Invalid duration');

    const contribution = value * unitMultipliers[unit];
    if (!Number.isSafeInteger(contribution)) throw new RangeError('Invalid duration');

    total += contribution;
    if (!Number.isSafeInteger(total)) throw new RangeError('Invalid duration');
  }

  return total;
}

export function parseDuration(text: string): number {
  const unitOrder: Record<string, number> = { h: 3, m: 2, s: 1, ms: 0 };
  const unitMs: Record<string, number> = { h: 3600000, m: 60000, s: 1000, ms: 1 };

  let pos = 0;
  const len = text.length;

  // Skip leading whitespace
  while (pos < len && (text[pos] === ' ' || text[pos] === '\t' || text[pos] === '\n' || text[pos] === '\r')) pos++;

  if (pos === len) throw new RangeError('Invalid duration: empty input');

  let total = 0;
  let lastOrder = 4; // Higher than any valid unit order
  let hasComponent = false;

  while (pos < len) {
    // Skip whitespace between components
    while (pos < len && (text[pos] === ' ' || text[pos] === '\t' || text[pos] === '\n' || text[pos] === '\r')) pos++;

    if (pos === len) break;

    // Parse digits (no sign, no fraction allowed)
    if (text[pos] < '0' || text[pos] > '9') throw new RangeError('Invalid duration');
    const numStart = pos;
    while (pos < len && text[pos] >= '0' && text[pos] <= '9') pos++;
    const numStr = text.slice(numStart, pos);

    // Parse unit — check 'ms' before 'm' to avoid ambiguity
    let unit: string;
    if (text.startsWith('ms', pos)) { unit = 'ms'; pos += 2; }
    else if (pos < len && text[pos] === 'h') { unit = 'h'; pos++; }
    else if (pos < len && text[pos] === 'm') { unit = 'm'; pos++; }
    else if (pos < len && text[pos] === 's') { unit = 's'; pos++; }
    else throw new RangeError('Invalid duration: unknown or missing unit');

    // Strictly descending order; duplicates are caught by >=
    const order = unitOrder[unit];
    if (order >= lastOrder) throw new RangeError('Invalid duration: out-of-order or duplicate unit');
    lastOrder = order;

    const val = Number(numStr);
    if (!Number.isSafeInteger(val)) throw new RangeError('Invalid duration: value exceeds MAX_SAFE_INTEGER');

    const ms = val * unitMs[unit];
    if (!Number.isSafeInteger(ms)) throw new RangeError('Invalid duration: component exceeds MAX_SAFE_INTEGER');

    total += ms;
    if (!Number.isSafeInteger(total)) throw new RangeError('Invalid duration: total exceeds MAX_SAFE_INTEGER');

    hasComponent = true;
  }

  if (!hasComponent) throw new RangeError('Invalid duration: empty input');

  return total;
}

export function parseDuration(text: string): number {
  const UNITS: { unit: string; mult: number }[] = [
    { unit: 'h',  mult: 3_600_000 },
    { unit: 'm',  mult:    60_000 },
    { unit: 's',  mult:     1_000 },
    { unit: 'ms', mult:         1 },
  ];

  const MAX = Number.MAX_SAFE_INTEGER;

  // Strip leading/trailing whitespace then reject empty
  const trimmed = text.trim();
  if (trimmed === '') throw new RangeError('Invalid duration: empty input');

  // ms must precede m in the alternation so the regex prefers the longer unit
  const componentRe = /^(\d+)(h|ms|m|s)/;

  let remaining = trimmed;
  let total = 0;
  let lastUnitIndex = -1;

  while (remaining.length > 0) {
    const match = componentRe.exec(remaining);
    if (!match) throw new RangeError('Invalid duration: unexpected input');

    const valueStr = match[1];
    const unitStr  = match[2];

    const unitIndex = UNITS.findIndex(u => u.unit === unitStr);

    // Strictly descending order (also rejects duplicates)
    if (unitIndex <= lastUnitIndex) {
      throw new RangeError('Invalid duration: out-of-order or duplicate unit');
    }
    lastUnitIndex = unitIndex;

    const value = Number(valueStr);

    // Guard: value itself must not exceed MAX
    if (value > MAX) throw new RangeError('Invalid duration: component value exceeds MAX_SAFE_INTEGER');

    const mult = UNITS[unitIndex].mult;

    // Guard: value * mult must not exceed MAX (avoid IEEE drift by integer division)
    if (value > Math.floor(MAX / mult)) {
      throw new RangeError('Invalid duration: total exceeds MAX_SAFE_INTEGER');
    }
    const contribution = value * mult;

    // Guard: running total must not exceed MAX
    if (contribution > MAX - total) {
      throw new RangeError('Invalid duration: total exceeds MAX_SAFE_INTEGER');
    }
    total += contribution;

    // Consume matched text then skip optional inter-component whitespace
    remaining = remaining.slice(match[0].length).replace(/^\s+/, '');
  }

  // We always enter the loop at least once (trimmed is non-empty) and any
  // failure to match a component throws, so reaching here means we parsed ≥1.
  return total;
}

export function parseDuration(text: string): number {
  // Full-string pattern: optional leading/trailing whitespace, one or more
  // components (digits immediately followed by a unit), optional whitespace
  // between components. Units tried longest-first so "ms" beats "m".
  const FULL = /^\s*\d+(?:ms|h|m|s)(?:\s*\d+(?:ms|h|m|s))*\s*$/;
  if (!FULL.test(text)) throw new RangeError('Invalid duration');

  const COMPONENT = /\d+(?:ms|h|m|s)/g;
  const components = text.match(COMPONENT)!;

  const ORDER: Record<string, number> = { h: 0, m: 1, s: 2, ms: 3 };
  const MULT: Record<string, number> = { h: 3600000, m: 60000, s: 1000, ms: 1 };
  const MAX = Number.MAX_SAFE_INTEGER;

  let lastOrder = -1;
  let total = 0;

  for (const comp of components) {
    const unit = comp.endsWith('ms') ? 'ms' : comp.slice(-1);
    const numStr = unit === 'ms' ? comp.slice(0, -2) : comp.slice(0, -1);

    // Strictly descending order (also rejects duplicates)
    const ord = ORDER[unit];
    if (ord <= lastOrder) throw new RangeError('Invalid duration');
    lastOrder = ord;

    const value = Number(numStr);
    if (value > MAX) throw new RangeError('Invalid duration');

    const contribution = value * MULT[unit];
    if (contribution > MAX) throw new RangeError('Invalid duration');

    total += contribution;
    if (total > MAX) throw new RangeError('Invalid duration');
  }

  return total;
}

export function parseDuration(text: string): number {
  const UNITS: Record<string, number> = { h: 3600000, m: 60000, s: 1000, ms: 1 };
  const UNIT_ORDER: Record<string, number> = { h: 3, m: 2, s: 1, ms: 0 };

  if (!/^\s*\d+(?:h|ms|m|s)(?:\s*\d+(?:h|ms|m|s))*\s*$/.test(text)) {
    throw new RangeError('Invalid duration');
  }

  const componentRe = /(\d+)(h|ms|m|s)/g;
  let total = 0;
  let lastOrder = Infinity;
  let match;

  while ((match = componentRe.exec(text)) !== null) {
    const value = Number(match[1]);
    const unit = match[2];
    const order = UNIT_ORDER[unit];

    if (order >= lastOrder) throw new RangeError('Invalid duration');
    if (value > Number.MAX_SAFE_INTEGER) throw new RangeError('Invalid duration');

    const ms = value * UNITS[unit];
    if (ms > Number.MAX_SAFE_INTEGER) throw new RangeError('Invalid duration');

    total += ms;
    if (total > Number.MAX_SAFE_INTEGER) throw new RangeError('Invalid duration');

    lastOrder = order;
  }

  return total;
}

