  const MAX = Number.MAX_SAFE_INTEGER;
  const re = /^\s*(?:(\d+)h\s*)?(?:(\d+)m(?!s)\s*)?(?:(\d+)s\s*)?(?:(\d+)ms\s*)?$/;
  const match = re.exec(text);
  if (!match) throw new RangeError('Invalid duration');

  const [, h, m, s, ms] = match;
  if (h === undefined && m === undefined && s === undefined && ms === undefined) {
    throw new RangeError('Invalid duration');
  }

  const components: Array<[string | undefined, number]> = [
    [h, 3600000],
    [m, 60000],
    [s, 1000],
    [ms, 1],
  ];

  let total = 0;
  for (const [raw, multiplier] of components) {
    if (raw === undefined) continue;
    const val = Number(raw);
    if (val > MAX) throw new RangeError('Invalid duration');
    const contribution = val * multiplier;
    if (contribution > MAX - total) throw new RangeError('Invalid duration');
    total += contribution;
  }

  return total;
}

const ORDER = { h: 0, m: 1, s: 2, ms: 3 } as const;
const MULT  = { h: 3600000, m: 60000, s: 1000, ms: 1 } as const;

export function parseDuration(text: string): number {
  let pos = 0;
  let lastOrder = -1;
  let total = 0;
  let found = false;

  while (pos < text.length && (text[pos] === ' ' || text[pos] === '\t')) pos++;

  while (pos < text.length) {
    const m = /^(\d+)(h|ms|m|s)/.exec(text.slice(pos));
    if (!m) throw new RangeError('Invalid duration');

    found = true;
    const unit = m[2] as keyof typeof ORDER;
    const ord = ORDER[unit];

    if (ord <= lastOrder) throw new RangeError('Invalid duration');
    lastOrder = ord;

    const val = Number(m[1]);
    if (!Number.isSafeInteger(val)) throw new RangeError('Invalid duration');

    total += val * MULT[unit];
    if (!Number.isSafeInteger(total)) throw new RangeError('Invalid duration');

    pos += m[0].length;
    while (pos < text.length && (text[pos] === ' ' || text[pos] === '\t')) pos++;
  }

  if (!found) throw new RangeError('Invalid duration');
  return total;
}

export function parseDuration(text: string): number {
  const MAX = Number.MAX_SAFE_INTEGER;
  const s = text.trim();
  if (s.length === 0) throw new RangeError('Invalid duration');

  let pos = 0;
  let total = 0;
  let lastUnit = -1;
  let count = 0;

  while (pos < s.length) {
    // Parse decimal digits only (no sign, no decimal point)
    const digitStart = pos;
    while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
    if (pos === digitStart) throw new RangeError('Invalid duration');
    const numStr = s.slice(digitStart, pos);

    // Parse unit: check 'ms' before 'm'/'s' to avoid prefix ambiguity
    let unitOrder: number;
    let unitMs: number;
    if (s.slice(pos, pos + 2) === 'ms') {
      unitOrder = 3; unitMs = 1; pos += 2;
    } else if (s[pos] === 'h') {
      unitOrder = 0; unitMs = 3_600_000; pos++;
    } else if (s[pos] === 'm') {
      unitOrder = 1; unitMs = 60_000; pos++;
    } else if (s[pos] === 's') {
      unitOrder = 2; unitMs = 1_000; pos++;
    } else {
      throw new RangeError('Invalid duration');
    }

    // Enforce strictly descending unit order (rejects duplicates and out-of-order)
    if (unitOrder <= lastUnit) throw new RangeError('Invalid duration');
    lastUnit = unitOrder;

    // Validate the parsed integer value
    const val = Number(numStr);
    if (val > MAX) throw new RangeError('Invalid duration');

    // Validate the component's millisecond contribution won't overflow
    if (unitMs > 1 && val > Math.floor(MAX / unitMs)) throw new RangeError('Invalid duration');
    const contrib = val * unitMs;

    // Validate running total
    if (total > MAX - contrib) throw new RangeError('Invalid duration');
    total += contrib;
    count++;

    // Skip optional whitespace between components (not between digit and unit)
    while (pos < s.length && /\s/.test(s[pos])) pos++;
  }

  if (count === 0) throw new RangeError('Invalid duration');
  return total;
}

export function parseDuration(text: string): number {
  const MAX = Number.MAX_SAFE_INTEGER; // 9007199254740991

  // Unit name → rank (strictly ascending h < m < s < ms)
  const unitRank: Record<string, number> = { h: 0, m: 1, s: 2, ms: 3 };
  // Unit name → ms multiplier
  const unitMult: Record<string, number> = { h: 3600000, m: 60000, s: 1000, ms: 1 };
  // Try 'ms' before 'm' to avoid 'm' consuming the 'm' in 'ms'
  const tryOrder = ['h', 'ms', 'm', 's'];

  const trimmed = text.trim();
  if (!trimmed) throw new RangeError('Invalid duration');

  let pos = 0;
  let total = 0;
  let lastRank = -1;
  let count = 0;

  while (pos < trimmed.length) {
    // Skip whitespace between components (but not between digits and unit)
    while (pos < trimmed.length && trimmed[pos] === ' ') pos++;
    if (pos >= trimmed.length) break;

    // Parse nonnegative integer digits (no sign, no dot)
    const digitStart = pos;
    while (pos < trimmed.length && trimmed[pos] >= '0' && trimmed[pos] <= '9') pos++;
    if (pos === digitStart) throw new RangeError('Invalid duration');

    const numStr = trimmed.slice(digitStart, pos);

    // Guard against astronomically long digit strings before Number conversion
    if (numStr.length > 16) throw new RangeError('Invalid duration');

    // Match a unit immediately after the digits (no whitespace allowed here)
    let unit: string | null = null;
    for (const u of tryOrder) {
      if (trimmed.startsWith(u, pos)) { unit = u; break; }
    }
    if (!unit) throw new RangeError('Invalid duration');
    pos += unit.length;

    // Enforce strictly descending h > m > s > ms order (no duplicates, no reversal)
    const rank = unitRank[unit];
    if (rank <= lastRank) throw new RangeError('Invalid duration');
    lastRank = rank;

    // Check the numeric value itself
    const val = Number(numStr);
    if (val > MAX) throw new RangeError('Invalid duration');

    // Check that val * multiplier won't exceed MAX (avoids float overflow)
    const mult = unitMult[unit];
    if (val > Math.floor(MAX / mult)) throw new RangeError('Invalid duration');
    const contribution = val * mult;

    // Check running total
    if (total > MAX - contribution) throw new RangeError('Invalid duration');
    total += contribution;

    count++;
  }

  if (count === 0) throw new RangeError('Invalid duration');
  return total;
}

export function parseDuration(text: string): number {
  const MAX = Number.MAX_SAFE_INTEGER;
